import { MetricsWarRoom } from "@/components/MetricsWarRoom";

export default function Page() {
  return <MetricsWarRoom />;
}

"use client";

import { useMemo, useState } from "react";
import { applyMetricsMutation, removeMetricsRecord, transitionMetricsRecord } from "@/lib/metric-engine";

const initialRecords = [
  {
    "id": "analytics-1",
    "label": "Activation",
    "value": "64%",
    "status": "+8%",
    "meta": "KPI bands"
  },
  {
    "id": "analytics-2",
    "label": "Net retention",
    "value": "112%",
    "status": "Healthy",
    "meta": "Funnel analysis",
    "parentId": "analytics-1"
  },
  {
    "id": "analytics-3",
    "label": "Churn risk",
    "value": "17",
    "status": "Watch",
    "meta": "Retention cohorts",
    "parentId": "analytics-1"
  }
];
const views = ["Overview","Funnels","Retention","Alerts"];
const transitions = ["Open","Investigating","Resolved"];

export function MetricsWarRoom({ initialView = views[0] }: { initialView?: string }) {
  const [view, setView] = useState(initialView);
  const [records, setRecords] = useState(initialRecords);
  const [input, setInput] = useState("");
  const [events, setEvents] = useState<string[]>(["MetricOS ready"]);
  const visible = useMemo(() => records.filter((record) => view === views[0] || record.status.toLowerCase().includes(view.toLowerCase()) || record.meta.toLowerCase().includes(view.toLowerCase())), [records, view]);
  function submit() {
    const next = applyMetricsMutation(records, { label: input || "Create alert", value: "New", status: "Created" });
    setRecords(next.records);
    setEvents((current) => [next.event, ...current]);
    setInput("");
  }
  function advance(id: string) {
    const next = transitionMetricsRecord(records, id, transitions);
    setRecords(next.records);
    setEvents((current) => [next.event, ...current]);
  }
  function remove(id: string) {
    const next = removeMetricsRecord(records, id);
    setRecords(next.records);
    setEvents((current) => [next.event, ...current]);
  }
  return (
    <main className="app">
      <header className="top"><div className="wrap" style={{display:"flex",justifyContent:"space-between",gap:12,alignItems:"center"}}><strong>MetricOS</strong><nav style={{display:"flex",gap:8,overflowX:"auto"}}>{views.map((item) => <button key={item} onClick={() => setView(item)} className="primary" style={{background:item===view?"var(--primary)":"#e2e8f0",color:item===view?"white":"#0f172a"}}>{item}</button>)}</nav></div></header>
      <section className="wrap hero">
        <div className="panel">
          <p style={{fontWeight:900,textTransform:"uppercase",letterSpacing:".16em",fontSize:12,color:"var(--primary)"}}>analytics</p>
          <h1 style={{fontSize:48,lineHeight:1,margin:"10px 0"}}>MetricOS</h1>
          <p style={{lineHeight:1.7,color:"#475569"}}>Build a SaaS analytics dashboard with metrics, alerts, cohorts, funnels, and retention workflows.</p>
          <div className="metric-deck" style={{marginTop:18}}>{visible.map((record) => <article key={record.id || record.label} className="card"><strong>{record.label}</strong><p style={{fontSize:28,fontWeight:850,margin:"8px 0"}}>{record.value}</p><span>{record.status}</span><div style={{display:"flex",gap:8,marginTop:12}}><button data-action="transition" onClick={() => advance(record.id)} className="primary" style={{padding:"8px 10px"}}>Resolve alert</button><button data-action="delete" onClick={() => remove(record.id)} className="primary" style={{padding:"8px 10px",background:"#fee2e2",color:"#991b1b"}}>Delete cohort</button></div></article>)}</div>
        </div>
        <aside className="panel">
          <h2>Create alert</h2>
          <p>Adds alert to monitoring queue</p>
          <textarea value={input} onChange={(event) => setInput(event.target.value)} placeholder="Metric, Threshold, Owner" style={{width:"100%",minHeight:110,border:"1px solid #cbd5e1",borderRadius:12,padding:12}} />
          <button onClick={submit} className="primary" style={{width:"100%",marginTop:10}}>create alert</button>
          <div style={{display:"grid",gap:8,marginTop:16}}>{events.map((event) => <div key={event} className="card">{event}</div>)}</div>
        </aside>
      </section>
    </main>
  );
}

export const interactionMap = [
  {
    "label": "Create alert",
    "type": "create",
    "target": "Alert",
    "result": "Adds metric alert to owner queue"
  },
  {
    "label": "Resolve alert",
    "type": "transition",
    "target": "Alert",
    "result": "Moves Open -> Investigating -> Resolved"
