  {
    "from": "Metric",
    "to": "Alert",
    "type": "one-to-many",
    "via": "metricId"
  },
  {
    "from": "Metric",
    "to": "Cohort",
    "type": "one-to-many",
    "via": "metricId"
  }
] as const;

export function assertRelationalSchema() {
  if (relationships.length < 2) throw new Error("Relational schema is required.");
  return relationships.map((relation) => relation.from + " -> " + relation.to);
}

import { applyMetricsMutation, removeMetricsRecord, transitionMetricsRecord } from "@/lib/metric-engine";

export const statusFlow = [
  "Open",
  "Investigating",
  "Resolved"
] as const;

export function handleMetricsAction(records: Array<{ id: string; label: string; value: string; status: string; meta?: string; parentId?: string }>, body: { action?: string; id?: string; label?: string; value?: string; status?: string }) {
  if (body.action === "transition" && body.id) return transitionMetricsRecord(records, body.id, [...statusFlow]);
  if (body.action === "delete" && body.id) return removeMetricsRecord(records, body.id);
  return applyMetricsMutation(records, { label: body.label || "Create alert", value: body.value || "New", status: body.status || statusFlow[0] || "Created" });
}

type RecordItem = { id: string; label: string; value: string; status: string; meta?: string; parentId?: string };

export function applyMetricsMutation(records: RecordItem[], input: Pick<RecordItem, "label" | "value" | "status">) {
  const created = { id: crypto.randomUUID?.() || String(Date.now()), ...input, meta: "create alert", parentId: records[0]?.id };
  return {
    records: [created, ...records],
    event: "create alert: " + created.label,
  };
}

export function transitionMetricsRecord(records: RecordItem[], id: string, flow: string[]) {
  let changed = "No record changed";
  const nextRecords = records.map((record) => {
    if (record.id !== id) return record;
    const index = flow.indexOf(record.status);
    const status = flow[Math.min(index + 1, flow.length - 1)] || "Done";
    changed = record.label + " moved to " + status;
    return { ...record, status };
  });
  return { records: nextRecords, event: changed };
}

export function removeMetricsRecord(records: RecordItem[], id: string) {
  const target = records.find((record) => record.id === id);
  return {
    records: records.filter((record) => record.id !== id && record.parentId !== id),
    event: target ? "Removed " + target.label : "Removed record",
  };
}

